/// <summary>
/// CB233_TOReceiptDetails
/// CB256_PurchaseOrderReceiptDetails
/// The class to implement task handling of the sys operation job.
/// </summary>
public abstract class METSysOperationTaskService extends SysOperationServiceBase
{
    METSysOperationTaskDataContract dataContract;
    Batch                           batchTask;
    Batch                           batchTaskCurrent;
    BatchHeader                     batchHeader;
    RefRecId                        batchJobId;
    RefRecId                        headerTaskId;
    boolean                         isExecutingInBatch, isMainBatchTask;
    UserConnection                  secondConnection;
    TransDate                       todayDate;
    str                             errorMsg;

}

Method.Source:
    /// <summary>
    /// Runs the processing of the tasks.
    /// </summary>
    /// <param name = "_dataContract">Service class data contract</param>
    protected void processInternal(METSysOperationTaskDataContract  _dataContract)
    {
        #OCCRetryCount

        try
        {
            dataContract = _dataContract;

            this.initialise();

            if (!this.validate())
            {
                error(errorMsg);
                
                if (isExecutingInBatch)
                {
                    //ensure batch status is "Error"
                    throw Exception::Error;
                }
                else
                {
                    //dont throw error when run from GUI
                    return;
                }
            }

            this.processTask(true);

            if (isMainBatchTask)
            {
                //last run of main task thread to make sure all others have been processed
                this.processTask(false);
            }
        }
        catch (Exception::UpdateConflict)
        {
            if (appl.ttsLevel() == 0)
            {
                if (xSession::currentRetryCount() >= #RetryNum)
                {
                    error(errorMsg);
                    throw Exception::UpdateConflictNotRecovered;
                }
                else
                {
                    retry;
                }
            }
            else
            {
                error(errorMsg);
                throw Exception::UpdateConflict;
            }
        }
        catch (Exception::Deadlock)
        {
            if (appl.ttsLevel() == 0)
            {
                if (xSession::currentRetryCount() >= #RetryNum)
                {
                    error(errorMsg);
                    throw Exception::UpdateConflictNotRecovered;
                }
                else
                {
                    retry;
                }
            }
            else
            {
                error(errorMsg);
                throw Exception::Deadlock;
            }
        }
        catch
        {
            this.updateOnError();
            error(errorMsg);
        }
    }

    /// <summary>
    /// Updates the record upon error.
    /// </summary>
    protected void updateOnError()
    {

    }

    /// <summary>
    /// Runs tasks of the task service class.
    /// </summary>
    /// <param name = "_readPast">Table read past setting</param>
    protected abstract void processTask(boolean _readPast)
    {

    }

/// <summary>
/// Initializes the object.
/// </summary>
protected void initialise()
{
    isMainBatchTask    = dataContract.parmIsMainBatchTask();
    batchTaskCurrent   = this.getCurrentBatchTask();
    batchJobId         = batchTaskCurrent.BatchJobId;
    headerTaskId       = batchTaskCurrent.RecId;
    batchHeader        = BatchHeader::construct(batchJobId);
    isExecutingInBatch = batchTaskCurrent ? true : false;
    secondConnection   = new UserConnection();
    todayDate          = DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone());
    errorMsg           = strFmt("@MET:METBatchTaskFailed", classId2Name(classIdGet(this)));
}

/// <summary>
/// Validates the task process.
/// Can be overriden to implement custom validation.
/// </summary>
/// <returns>The result of the validation</returns>
protected boolean validate()
{
    return true;
}
